{
  "task": "format_questions_to_latex",
  "questions": [
    {
      "source_id": "1",
      "stem": "A survey robot starts at the origin of a coordinate system and detects a beacon at position \\(\\vec r = 8\\hat i - 15\\hat j\\), where distances are measured in meters. Which of the following statements is correct?",
      "options": [
        {
          "key": "A",
          "text": "The distance from the robot to the beacon is \\(23\\,\\text{m}\\).",
          "is_correct": false,
          "explanation": "This adds the component magnitudes, \\(8+15\\), instead of finding the vector magnitude. The distance must be computed with the Pythagorean relation, not by simple component addition."
        },
        {
          "key": "B",
          "text": "The distance from the robot to the beacon is \\(17\\,\\text{m}\\).",
          "is_correct": true,
          "explanation": "The distance from the origin to a point is the magnitude of its position vector. Using \\(|\\vec r|=\\sqrt{x^2+y^2}\\), we get \\(|\\vec r|=\\sqrt{8^2+(-15)^2}=\\sqrt{64+225}=\\sqrt{289}=17\\,\\text{m}\\). Therefore this statement is correct."
        },
        {
          "key": "C",
          "text": "The distance from the robot to the beacon is \\(15\\,\\text{m}\\).",
          "is_correct": false,
          "explanation": "This uses only the \\(y\\)-component magnitude and ignores the \\(x\\)-component. That is a component-versus-magnitude mistake."
        },
        {
          "key": "D",
          "text": "The distance from the robot to the beacon is \\(8\\,\\text{m}\\).",
          "is_correct": false,
          "explanation": "This uses only the \\(x\\)-component and ignores the \\(y\\)-component. A full 2D distance requires both perpendicular components."
        }
      ],
      "question_type": "multiple_choice",
      "skipped": false,
      "skip_reason": "",
      "answer": "",
      "parts": []
    },
    {
      "source_id": "2",
      "stem": "The displacement of a particle moving along the \\(x\\)-axis is given by \\(\\vec s(t)=\\big((2.4\\,\\text{m/s}^3)t^3-(1.8\\,\\text{m/s}^2)t^2\\big)\\hat i\\). Which of the following statements is correct?",
      "options": [
        {
          "key": "A",
          "text": "This motion has constant acceleration.",
          "is_correct": false,
          "explanation": "This comes from not differentiating the cubic displacement term completely. Because \\(s_x\\) contains a \\(t^3\\) term, the acceleration depends on time and is not constant."
        },
        {
          "key": "B",
          "text": "The acceleration at \\(t=0\\) is \\(-1.8\\,\\text{m/s}^2\\).",
          "is_correct": false,
          "explanation": "This mistakes the coefficient of the \\(t^2\\) term in displacement for the acceleration itself. You must take two time derivatives before evaluating at \\(t=0\\)."
        },
        {
          "key": "C",
          "text": "The magnitude of the acceleration at \\(t=0\\) is \\(3.6\\,\\text{m/s}^2\\).",
          "is_correct": true,
          "explanation": "Acceleration is the second derivative of displacement. From \\(s_x=(2.4)t^3-(1.8)t^2\\), we get \\(v_x=\\frac{ds_x}{dt}=7.2t^2-3.6t\\) and \\(a_x=\\frac{dv_x}{dt}=14.4t-3.6\\), so at \\(t=0\\), \\(a_x=-3.6\\,\\text{m/s}^2\\) and its magnitude is \\(3.6\\,\\text{m/s}^2\\)."
        },
        {
          "key": "D",
          "text": "The magnitude of the acceleration at \\(t=0\\) is \\(0\\,\\text{m/s}^2\\).",
          "is_correct": false,
          "explanation": "This usually comes from confusing initial velocity or displacement with acceleration. Evaluating the actual acceleration function at \\(t=0\\) does not give zero."
        }
      ],
      "question_type": "multiple_choice",
      "skipped": false,
      "skip_reason": "",
      "answer": "",
      "parts": []
    },
    {
      "source_id": "3",
      "stem": "A glider moves from position \\(\\vec r_A = 1\\hat i - 7\\hat j\\) to position \\(\\vec r_B = -5\\hat i + 1\\hat j\\) in \\(4\\,\\text{s}\\), where positions are measured in meters. Which of the following statements is correct?",
      "options": [
        {
          "key": "A",
          "text": "The distance traveled by the glider is \\(10\\,\\text{m}\\).",
          "is_correct": false,
          "explanation": "This confuses the magnitude of displacement with the actual path length traveled. From initial and final positions alone, the total distance traveled cannot be determined."
        },
        {
          "key": "B",
          "text": "The speed at \\(t=0\\) must be \\(2.5\\,\\text{m/s}\\).",
          "is_correct": false,
          "explanation": "This incorrectly treats displacement magnitude divided by time as the instantaneous speed at the start. The given data are only enough to find an average based on displacement, not the speed at \\(t=0\\)."
        },
        {
          "key": "C",
          "text": "The acceleration at \\(t=0\\) must be \\(0.625\\,\\text{m/s}^2\\).",
          "is_correct": false,
          "explanation": "This invents an instantaneous acceleration from only two positions and one time interval. That information is insufficient to determine acceleration at a specific instant."
        },
        {
          "key": "D",
          "text": "None of the above is correct.",
          "is_correct": true,
          "explanation": "The displacement is \\(\\Delta\\vec r=\\vec r_B-\\vec r_A=(-6)\\hat i+8\\hat j\\), so its magnitude is \\(|\\Delta\\vec r|=\\sqrt{(-6)^2+8^2}=\\sqrt{100}=10\\,\\text{m}\\). However, that value is the displacement magnitude, not necessarily the distance traveled, and neither the instantaneous speed at \\(t=0\\) nor the instantaneous acceleration at \\(t=0\\) can be deduced from the given information alone. Therefore none of A, B, or C must be true."
        }
      ],
      "question_type": "multiple_choice",
      "skipped": false,
      "skip_reason": "",
      "answer": "",
      "parts": []
    }
